//#region src/data/adapters/bybitAdapter.ts
var BybitAdapter = class {
	constructor() {
		this.id = "BYBIT";
		this.name = "Bybit Spot V5 Public";
		this.capabilities = {
			supportsPublicRest: true,
			supportsWebSocket: true,
			rateLimitPerMinute: 600,
			notes: "Official Bybit V5 Public Spot Market API."
		};
	}
	isSymbolSupported(symbol) {
		return this.toExchangeSymbol(symbol) !== null;
	}
	toExchangeSymbol(symbol) {
		const cleaned = symbol.replace(/[\/\-_]/g, "").toUpperCase();
		if (cleaned.endsWith("USDT") && cleaned.length >= 6) return cleaned;
		return null;
	}
	toBybitInterval(timeframe) {
		switch (timeframe) {
			case "1m": return "1";
			case "5m": return "5";
			case "15m": return "15";
			default: return "1";
		}
	}
	async getCandles(symbol, timeframe, limit = 100) {
		const bybitSymbol = this.toExchangeSymbol(symbol);
		if (!bybitSymbol) throw new Error(`[Bybit] Symbol ${symbol} is not a supported spot pair on Bybit.`);
		const url = `https://api.bybit.com/v5/market/kline?category=spot&symbol=${bybitSymbol}&interval=${this.toBybitInterval(timeframe)}&limit=${Math.min(limit, 200)}`;
		const controller = new AbortController();
		const timeoutId = setTimeout(() => controller.abort(), 6e3);
		const res = await fetch(url, { signal: controller.signal });
		clearTimeout(timeoutId);
		if (!res.ok) throw new Error(`[Bybit] HTTP ${res.status}: ${res.statusText}`);
		const json = await res.json();
		if (json.retCode !== 0 || !json.result?.list) throw new Error(`[Bybit] API error (${json.retCode}): ${json.retMsg || "Unknown error"}`);
		return [...json.result.list].sort((a, b) => Number(a[0]) - Number(b[0])).map((item) => ({
			exchange: this.id,
			symbol,
			timeframe,
			timestamp: Number(item[0]),
			open: parseFloat(item[1]),
			high: parseFloat(item[2]),
			low: parseFloat(item[3]),
			close: parseFloat(item[4]),
			volume: parseFloat(item[5]),
			isFinal: true
		}));
	}
	async getLatestPrice(symbol) {
		const bybitSymbol = this.toExchangeSymbol(symbol);
		if (!bybitSymbol) throw new Error(`[Bybit] Symbol ${symbol} is not supported on Bybit.`);
		const url = `https://api.bybit.com/v5/market/tickers?category=spot&symbol=${bybitSymbol}`;
		const controller = new AbortController();
		const timeoutId = setTimeout(() => controller.abort(), 5e3);
		const res = await fetch(url, { signal: controller.signal });
		clearTimeout(timeoutId);
		if (!res.ok) throw new Error(`[Bybit] Ticker HTTP ${res.status}: ${res.statusText}`);
		const ticker = (await res.json()).result?.list?.[0];
		if (!ticker || !ticker.lastPrice) throw new Error(`[Bybit] No ticker data found for ${symbol}.`);
		const price = parseFloat(ticker.lastPrice);
		return {
			exchange: this.id,
			symbol,
			price,
			timestamp: Date.now(),
			source: "Bybit Spot V5 API",
			bid: ticker.bid1Price ? parseFloat(ticker.bid1Price) : void 0,
			ask: ticker.ask1Price ? parseFloat(ticker.ask1Price) : void 0,
			volume24h: ticker.volume24h ? parseFloat(ticker.volume24h) : void 0
		};
	}
	subscribeLive(symbol, timeframe, onCandle, onError) {
		const bybitSymbol = this.toExchangeSymbol(symbol);
		if (!bybitSymbol) {
			onError?.(/* @__PURE__ */ new Error(`[Bybit] Cannot subscribe: ${symbol} is unsupported.`));
			return () => {};
		}
		let isDisposed = false;
		let ws = null;
		let pingInterval = null;
		let reconnectTimeout = null;
		const interval = this.toBybitInterval(timeframe);
		const connect = () => {
			if (isDisposed) return;
			const wsUrl = "wss://stream.bybit.com/v5/public/spot";
			try {
				ws = new WebSocket(wsUrl);
				ws.onopen = () => {
					const subMsg = {
						op: "subscribe",
						args: [`kline.${interval}.${bybitSymbol}`]
					};
					ws?.send(JSON.stringify(subMsg));
					pingInterval = setInterval(() => {
						if (ws && ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify({ op: "ping" }));
					}, 2e4);
				};
				ws.onmessage = (event) => {
					try {
						const data = JSON.parse(event.data);
						if (data?.topic?.startsWith("kline") && Array.isArray(data?.data)) for (const k of data.data) {
							const candle = {
								exchange: this.id,
								symbol,
								timeframe,
								timestamp: Number(k.start),
								open: parseFloat(k.open),
								high: parseFloat(k.high),
								low: parseFloat(k.low),
								close: parseFloat(k.close),
								volume: parseFloat(k.volume),
								isFinal: Boolean(k.confirm)
							};
							onCandle(candle, candle.isFinal);
						}
					} catch (e) {
						onError?.(e);
					}
				};
				ws.onerror = () => {
					onError?.(/* @__PURE__ */ new Error("[Bybit WS] Connection error"));
				};
				ws.onclose = () => {
					clearInterval(pingInterval);
					if (!isDisposed) reconnectTimeout = setTimeout(connect, 3e3);
				};
			} catch (err) {
				onError?.(err);
			}
		};
		connect();
		return () => {
			isDisposed = true;
			clearInterval(pingInterval);
			if (reconnectTimeout) clearTimeout(reconnectTimeout);
			if (ws) {
				ws.onclose = null;
				ws.onerror = null;
				ws.close();
				ws = null;
			}
		};
	}
};
