//#region src/data/adapters/okxAdapter.ts
var OkxAdapter = class {
	constructor() {
		this.id = "OKX";
		this.name = "OKX V5 Public Market";
		this.capabilities = {
			supportsPublicRest: true,
			supportsWebSocket: true,
			rateLimitPerMinute: 600,
			notes: "Official OKX V5 Public Spot Market API."
		};
	}
	isSymbolSupported(symbol) {
		return this.toExchangeSymbol(symbol) !== null;
	}
	toExchangeSymbol(symbol) {
		const cleaned = symbol.replace(/[\/]/g, "-").toUpperCase();
		if (cleaned.endsWith("-USDT")) return cleaned;
		return null;
	}
	async getCandles(symbol, timeframe, limit = 100) {
		const instId = this.toExchangeSymbol(symbol);
		if (!instId) throw new Error(`[OKX] Symbol ${symbol} is not a supported spot pair on OKX.`);
		const url = `https://www.okx.com/api/v5/market/candles?instId=${instId}&bar=${timeframe}&limit=${Math.min(limit, 100)}`;
		const controller = new AbortController();
		const timeoutId = setTimeout(() => controller.abort(), 6e3);
		const res = await fetch(url, { signal: controller.signal });
		clearTimeout(timeoutId);
		if (!res.ok) throw new Error(`[OKX] HTTP ${res.status}: ${res.statusText}`);
		const json = await res.json();
		if (json.code !== "0" || !Array.isArray(json.data)) throw new Error(`[OKX] API error (${json.code}): ${json.msg || "Unknown error"}`);
		return [...json.data].sort((a, b) => Number(a[0]) - Number(b[0])).map((item) => ({
			exchange: this.id,
			symbol,
			timeframe,
			timestamp: Number(item[0]),
			open: parseFloat(item[1]),
			high: parseFloat(item[2]),
			low: parseFloat(item[3]),
			close: parseFloat(item[4]),
			volume: parseFloat(item[5]),
			isFinal: item[8] === "1"
		}));
	}
	async getLatestPrice(symbol) {
		const instId = this.toExchangeSymbol(symbol);
		if (!instId) throw new Error(`[OKX] Symbol ${symbol} is not supported on OKX.`);
		const url = `https://www.okx.com/api/v5/market/ticker?instId=${instId}`;
		const controller = new AbortController();
		const timeoutId = setTimeout(() => controller.abort(), 5e3);
		const res = await fetch(url, { signal: controller.signal });
		clearTimeout(timeoutId);
		if (!res.ok) throw new Error(`[OKX] Ticker HTTP ${res.status}: ${res.statusText}`);
		const ticker = (await res.json()).data?.[0];
		if (!ticker || !ticker.last) throw new Error(`[OKX] No ticker data found for ${symbol}.`);
		const price = parseFloat(ticker.last);
		return {
			exchange: this.id,
			symbol,
			price,
			timestamp: Number(ticker.ts) || Date.now(),
			source: "OKX V5 Public Spot API",
			bid: ticker.bidPx ? parseFloat(ticker.bidPx) : void 0,
			ask: ticker.askPx ? parseFloat(ticker.askPx) : void 0,
			volume24h: ticker.vol24h ? parseFloat(ticker.vol24h) : void 0
		};
	}
	subscribeLive(symbol, timeframe, onCandle, onError) {
		const instId = this.toExchangeSymbol(symbol);
		if (!instId) {
			onError?.(/* @__PURE__ */ new Error(`[OKX] Cannot subscribe: ${symbol} is unsupported.`));
			return () => {};
		}
		let isDisposed = false;
		let ws = null;
		let pingInterval = null;
		let reconnectTimeout = null;
		const connect = () => {
			if (isDisposed) return;
			const wsUrl = "wss://ws.okx.com:8443/ws/v5/public";
			try {
				ws = new WebSocket(wsUrl);
				ws.onopen = () => {
					const subMsg = {
						op: "subscribe",
						args: [{
							channel: `candle${timeframe}`,
							instId
						}]
					};
					ws?.send(JSON.stringify(subMsg));
					pingInterval = setInterval(() => {
						if (ws && ws.readyState === WebSocket.OPEN) ws.send("ping");
					}, 25e3);
				};
				ws.onmessage = (event) => {
					try {
						if (event.data === "pong") return;
						const data = JSON.parse(event.data);
						if (data?.data && Array.isArray(data.data)) for (const item of data.data) {
							const candle = {
								exchange: this.id,
								symbol,
								timeframe,
								timestamp: Number(item[0]),
								open: parseFloat(item[1]),
								high: parseFloat(item[2]),
								low: parseFloat(item[3]),
								close: parseFloat(item[4]),
								volume: parseFloat(item[5]),
								isFinal: item[8] === "1"
							};
							onCandle(candle, candle.isFinal);
						}
					} catch (e) {
						onError?.(e);
					}
				};
				ws.onerror = () => {
					onError?.(/* @__PURE__ */ new Error("[OKX WS] Connection error"));
				};
				ws.onclose = () => {
					clearInterval(pingInterval);
					if (!isDisposed) reconnectTimeout = setTimeout(connect, 3e3);
				};
			} catch (err) {
				onError?.(err);
			}
		};
		connect();
		return () => {
			isDisposed = true;
			clearInterval(pingInterval);
			if (reconnectTimeout) clearTimeout(reconnectTimeout);
			if (ws) {
				ws.onclose = null;
				ws.onerror = null;
				ws.close();
				ws = null;
			}
		};
	}
};
