async function checkBackendHealth(timeoutMs = 6e3) {
	const startTime = Date.now();
	let targetUrl = getApiUrl("/api/health");
	const controller = new AbortController();
	const timer = setTimeout(() => controller.abort(), timeoutMs);
	try {
		const res = await fetch(targetUrl, {
			method: "GET",
			headers: { Accept: "application/json" },
			signal: controller.signal
		});
		clearTimeout(timer);
		const latencyMs = Date.now() - startTime;
		if (res.ok) return {
			ok: true,
			latencyMs,
			url: targetUrl
		};
		if (targetUrl !== "/api/health" && typeof window !== "undefined") try {
			if ((await fetch("/api/health", {
				method: "GET",
				headers: { Accept: "application/json" }
			})).ok) {
				setCustomApiUrl("");
				return {
					ok: true,
					latencyMs: Date.now() - startTime,
					url: "/api/health"
				};
			}
		} catch {}
		return {
			ok: false,
			latencyMs,
			url: targetUrl,
			error: `HTTP ${res.status}`
		};
	} catch (err) {
		clearTimeout(timer);
		if (targetUrl !== "/api/health" && typeof window !== "undefined") try {
			if ((await fetch("/api/health", {
				method: "GET",
				headers: { Accept: "application/json" }
			})).ok) {
				setCustomApiUrl("");
				return {
					ok: true,
					latencyMs: Date.now() - startTime,
					url: "/api/health"
				};
			}
		} catch {}
		return {
			ok: false,
			latencyMs: Date.now() - startTime,
			url: targetUrl,
			error: err.name === "AbortError" ? "Connection timeout" : err.message || "Network unreachable"
		};
	}
}
