function formatPrice(price, decimals = 5) {
	if (price === void 0 || price === null || isNaN(price)) return "0.00000";
	return price.toFixed(decimals);
}
function formatTime(timestamp) {
	if (!timestamp) return "--:--:--";
	return new Date(timestamp).toLocaleTimeString([], {
		hour: "2-digit",
		minute: "2-digit",
		second: "2-digit",
		hour12: false
	});
}
function getPriceChangePip(entry, current, decimals) {
	const diff = current - entry;
	const isPositive = diff >= 0;
	const pips = (diff * Math.pow(10, decimals === 5 ? 4 : decimals === 3 ? 2 : 2)).toFixed(1);
	return {
		diff,
		isPositive,
		pipText: `${isPositive ? "+" : ""}${pips} pips`
	};
}
