	async processNativeFrameData(frame, isSingleScan = false) {
		if (!this.isScanningActive && !isSingleScan && !this.isSingleScanInProgress) return;
		const allowance = authService.checkScanAllowance();
		if (!allowance.allowed) {
			this.errorMessage = allowance.reasonBn || "আপনার স্ক্যান লিমিট শেষ হয়েছে।";
			this.haltRecurringScanKeepResult(this.errorMessage);
			return;
		}
		this.latestProcessedSequenceId = frame.sequenceId;
		this.latestFrameCount = frame.sequenceId;
		this.latestFrameTimestamp = frame.timestamp;
		this.latestResolution = `${frame.width}x${frame.height}`;
		this.captureState = "RUNNING";
		this.isProcessingFrame = true;
		this.lastProcessingStartTime = Date.now();
		this.aiState = "ANALYZING";
		this.notify();
		const startTime = Date.now();
		const controller = new AbortController();
		const timeout = setTimeout(() => controller.abort(), 22e3);
		try {
			const activeProfile = tradingProfileService.getActiveProfileId();
			const zoomedCandleBase64 = await this.buildZoomedRightCandleCrop(frame.imageBase64);
			const res = await fetch(getApiUrl("/api/agent/vision/analyze-frame"), {
				method: "POST",
				headers: { "Content-Type": "application/json" },
				body: JSON.stringify({
					imageBase64: frame.imageBase64,
					zoomedCandleBase64,
					mimeType: "image/jpeg",
					frameCapturedAt: frame.timestamp,
					tradingProfile: activeProfile,
					activeProfileRules: agentLearningService.getActiveProfilePromptContext(activeProfile)
				}),
				signal: controller.signal
			});
			clearTimeout(timeout);
			const latencyMs = Date.now() - startTime;
			this.latestApiLatencyMs = latencyMs;
			if (!this.isScanningActive && !isSingleScan && !this.isSingleScanInProgress || this.latestProcessedSequenceId > frame.sequenceId) return;
			if (res.ok) {
				const data = await res.json();
				if (data && data.ok && data.result) {
					const result = data.result;
					this.consecutiveNetworkFailures = 0;
					this.lastErrorReason = null;
					this.errorMessage = null;
					this.aiState = "READY";
					this.processResult(result, latencyMs);
				} else {
					const localResult = await this.analyzeFrameLocally(frame.imageBase64, frame.timestamp);
					this.aiState = "READY";
					this.lastErrorReason = null;
					this.errorMessage = null;
					this.processResult(localResult, latencyMs);
				}
			} else {
				const localResult = await this.analyzeFrameLocally(frame.imageBase64, frame.timestamp);
				this.aiState = "READY";
				this.lastErrorReason = null;
				this.errorMessage = null;
				this.processResult(localResult, latencyMs);
			}
			if ((await authService.recordCompletedScan("native_screen")).exhaustedAfter) this.haltRecurringScanKeepResult("নির্ধারিত স্ক্যান লিমিট পূর্ণ হয়েছে।");
		} catch (err) {
			clearTimeout(timeout);
			const latencyMs = Date.now() - startTime;
			this.latestApiLatencyMs = latencyMs;
			const localResult = await this.analyzeFrameLocally(frame.imageBase64, frame.timestamp);
			this.aiState = "READY";
			this.lastErrorReason = null;
			this.errorMessage = null;
			this.processResult(localResult, latencyMs);
			if ((await authService.recordCompletedScan("native_screen_local")).exhaustedAfter) this.haltRecurringScanKeepResult("নির্ধারিত স্ক্যান লিমিট পূর্ণ হয়েছে।");
		} finally {
			this.isProcessingFrame = false;
			this.notify();
		}
	}
	/**
	* Creates a 2x zoomed close-up crop of the rightmost chart region (last 6-8 candles + live price line + timer)
	* so Gemini Vision can inspect closed vs forming candle bodies and 1px wicks with crisp clarity.
	*/
	async buildZoomedRightCandleCrop(imageBase64) {
		if (typeof document === "undefined" || !imageBase64) return void 0;
		return new Promise((resolve) => {
			try {
				const img = new Image();
				img.onload = () => {
					try {
						const w = img.naturalWidth || img.width || 0;
						const h = img.naturalHeight || img.height || 0;
						if (w < 120 || h < 120) return resolve(void 0);
						const isPortrait = h > w;
						const sx = Math.floor(w * (isPortrait ? .44 : .54));
						const sy = Math.floor(h * (isPortrait ? .16 : .08));
						const sw = Math.max(80, Math.floor(w * (isPortrait ? .54 : .44)));
						const sh = Math.max(80, Math.floor(h * (isPortrait ? .58 : .8)));
						const cropCanvas = document.createElement("canvas");
						const outW = Math.min(1200, Math.max(sw, Math.round(sw * 2.2)));
						const outH = Math.round(sh / sw * outW);
						cropCanvas.width = outW;
						cropCanvas.height = outH;
						const cCtx = cropCanvas.getContext("2d");
						if (!cCtx) return resolve(void 0);
						cCtx.imageSmoothingEnabled = true;
						cCtx.imageSmoothingQuality = "high";
						cCtx.drawImage(img, sx, sy, sw, sh, 0, 0, outW, outH);
						resolve(cropCanvas.toDataURL("image/jpeg", .92));
					} catch {
						resolve(void 0);
					}
				};
				img.onerror = () => resolve(void 0);
				img.src = imageBase64.startsWith("data:") ? imageBase64 : `data:image/jpeg;base64,${imageBase64}`;
			} catch {
				resolve(void 0);
			}
		});
	}
