		postStep(2, "২/৫ ক্যান্ডেল", "OHLC ও টাইমার");
		await new Promise((r) => setTimeout(r, 320));
		postStep(3, "৩/৫ মাল্টি-TF", "১৫M · ৫M · ১M");
		await new Promise((r) => setTimeout(r, 320));
		postStep(4, "৪/৫ ফিল্টার", "ট্রেন্ড ও ভলিউম");
		await new Promise((r) => setTimeout(r, 320));
