			direction: this.latestResult.direction,
			confidence: this.latestResult.confidence,
			durationText: this.expirySecondsLeft > 0 ? `${String(Math.floor(this.expirySecondsLeft / 60)).padStart(2, "0")}:${String(this.expirySecondsLeft % 60).padStart(2, "0")}` : "--:--",
			verdictTitle: this.latestResult.direction === "UP" ? "▲ CALL" : this.latestResult.direction === "DOWN" ? "▼ PUT" : "⏸ WAIT",
			reasonText: this.latestResult.visionData?.symbol || "সিগন্যাল প্রস্তুত",
			latencyMs: 0,
